import { PageHeader } from '@/features/shell/PageHeader'
import { useNotifications } from '@/app/providers/NotificationProvider'
import { NotificationItem } from '@/shared/ui/NotificationItem'
import { Bell } from 'lucide-react'

export function NotificationsPage() {
  const { notifications, unreadCount, markRead, markAllRead } = useNotifications()

  return (
    <div className="flex flex-col h-full overflow-hidden">
      <PageHeader
        title="Notifications"
        subtitle={`${unreadCount} unread`}
        actions={
          unreadCount > 0 ? (
            <button onClick={markAllRead} className="text-xs text-accent hover:underline">Mark all read</button>
          ) : undefined
        }
      />
      <div className="flex-1 overflow-y-auto">
        {notifications.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full gap-3 text-muted-foreground">
            <Bell size={32} />
            <p>No notifications</p>
          </div>
        ) : (
          <div className="max-w-2xl mx-auto p-4 flex flex-col gap-1">
            {notifications.map((n) => (
              <NotificationItem key={n.id} notification={n} onRead={markRead} />
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
